-- IDM OS PostgreSQL baseline. Applied by scripts/postgres-migrate.ts.
-- Timestamps are stored as timestamptz; money remains integer minor units.
CREATE TABLE users (id text PRIMARY KEY, email text NOT NULL UNIQUE, contact_email text, phone text, display_name text NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE INDEX users_active_idx ON users (is_active);
CREATE TABLE roles (id text PRIMARY KEY, key text NOT NULL UNIQUE, display_name text NOT NULL, description text NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE user_roles (user_id text NOT NULL REFERENCES users(id) ON DELETE RESTRICT, role_id text NOT NULL REFERENCES roles(id) ON DELETE RESTRICT, assigned_at timestamptz NOT NULL, assigned_by_user_id text REFERENCES users(id) ON DELETE RESTRICT, PRIMARY KEY (user_id, role_id));
CREATE INDEX user_roles_role_idx ON user_roles(role_id);
CREATE TABLE auth_identities (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE RESTRICT, provider text NOT NULL, provider_account_id text NOT NULL, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, UNIQUE(provider, provider_account_id));
CREATE INDEX auth_identities_user_idx ON auth_identities(user_id);
CREATE TABLE user_pin_credentials (user_id text PRIMARY KEY REFERENCES users(id) ON DELETE RESTRICT, pin_hash text NOT NULL, salt text NOT NULL, failed_attempts integer NOT NULL DEFAULT 0 CHECK (failed_attempts >= 0), locked_until timestamptz, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE app_unlock_sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE RESTRICT, token_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL, last_active_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE INDEX app_unlock_sessions_user_active_idx ON app_unlock_sessions(user_id, revoked_at);
CREATE INDEX app_unlock_sessions_expiry_idx ON app_unlock_sessions(expires_at);
CREATE TABLE branding_assets (id text PRIMARY KEY, storage_key text NOT NULL UNIQUE, sha256 text NOT NULL UNIQUE CHECK (length(sha256)=64), mime_type text NOT NULL CHECK (mime_type='image/png'), byte_size integer NOT NULL CHECK (byte_size > 0 AND byte_size <= 524288), width integer NOT NULL CHECK (width > 0 AND width <= 512), height integer NOT NULL CHECK (height > 0 AND height <= 512), created_at timestamptz NOT NULL, created_by_user_id text NOT NULL REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE application_branding (id text PRIMARY KEY CHECK (id='default'), app_icon_asset_id text REFERENCES branding_assets(id) ON DELETE RESTRICT, revision integer NOT NULL CHECK (revision >= 0), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, updated_by_user_id text NOT NULL REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE financial_accounts (id text PRIMARY KEY, name text NOT NULL, kind text NOT NULL CHECK (kind IN ('CASH','PETTY_CASH','BANK','OTHER')), description text, currency text NOT NULL CHECK (currency ~ '^[A-Z]{3}$'), is_active boolean NOT NULL DEFAULT true, archived_at timestamptz, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, created_by_user_id text REFERENCES users(id) ON DELETE RESTRICT, updated_by_user_id text REFERENCES users(id) ON DELETE RESTRICT);
CREATE INDEX financial_accounts_active_idx ON financial_accounts(is_active);
CREATE INDEX financial_accounts_kind_idx ON financial_accounts(kind);
CREATE TABLE financial_transactions (id text PRIMARY KEY, type text NOT NULL CHECK (type IN ('SALE','COLLECTION','INCOME','EXPENSE','PURCHASE','PAYMENT','TRANSFER','ADJUSTMENT')), status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','POSTED','VOIDED')), occurred_at timestamptz NOT NULL, reference text, description text, category text, source text NOT NULL DEFAULT 'MANUAL', idempotency_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, created_by_user_id text REFERENCES users(id) ON DELETE RESTRICT, updated_by_user_id text REFERENCES users(id) ON DELETE RESTRICT, posted_at timestamptz, voided_at timestamptz, voided_by_user_id text REFERENCES users(id) ON DELETE RESTRICT, void_reason text, reversal_of_transaction_id text UNIQUE REFERENCES financial_transactions(id) ON DELETE RESTRICT, CHECK ((status='DRAFT' AND posted_at IS NULL AND voided_at IS NULL AND voided_by_user_id IS NULL AND void_reason IS NULL) OR (status='POSTED' AND posted_at IS NOT NULL AND voided_at IS NULL AND voided_by_user_id IS NULL AND void_reason IS NULL) OR (status='VOIDED' AND posted_at IS NOT NULL AND voided_at IS NOT NULL AND voided_by_user_id IS NOT NULL AND void_reason IS NOT NULL)), CHECK (reversal_of_transaction_id IS NULL OR reversal_of_transaction_id <> id));
CREATE INDEX financial_transactions_status_date_idx ON financial_transactions(status, occurred_at);
CREATE INDEX financial_transactions_type_date_idx ON financial_transactions(type, occurred_at);
CREATE INDEX financial_transactions_source_date_idx ON financial_transactions(source, occurred_at);
CREATE TABLE financial_movements (id text PRIMARY KEY, transaction_id text NOT NULL REFERENCES financial_transactions(id) ON DELETE RESTRICT, account_id text NOT NULL REFERENCES financial_accounts(id) ON DELETE RESTRICT, amount_minor bigint NOT NULL CHECK (amount_minor <> 0), created_at timestamptz NOT NULL, created_by_user_id text REFERENCES users(id) ON DELETE RESTRICT);
CREATE INDEX financial_movements_account_transaction_idx ON financial_movements(account_id, transaction_id);
CREATE INDEX financial_movements_transaction_idx ON financial_movements(transaction_id);
CREATE TABLE audit_logs (id text PRIMARY KEY, actor_user_id text REFERENCES users(id) ON DELETE RESTRICT, action text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, request_id text, before_json jsonb, after_json jsonb, metadata_json jsonb, occurred_at timestamptz NOT NULL, created_at timestamptz NOT NULL);
CREATE INDEX audit_logs_entity_date_idx ON audit_logs(entity_type, entity_id, occurred_at);
CREATE INDEX audit_logs_actor_date_idx ON audit_logs(actor_user_id, occurred_at);

CREATE FUNCTION idm_migration_mode() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT current_setting('idm.migration_mode', true) = 'on' $$;
CREATE FUNCTION idm_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT idm_migration_mode() THEN RAISE EXCEPTION 'immutable IDM record'; END IF; RETURN OLD; END $$;
CREATE TRIGGER audit_logs_immutable BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION idm_append_only();
CREATE TRIGGER branding_assets_immutable BEFORE UPDATE OR DELETE ON branding_assets FOR EACH ROW EXECUTE FUNCTION idm_append_only();
CREATE FUNCTION idm_movement_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF idm_migration_mode() THEN RETURN COALESCE(NEW, OLD); END IF; IF TG_OP='INSERT' AND COALESCE((SELECT status FROM financial_transactions WHERE id=NEW.transaction_id),'') <> 'DRAFT' THEN RAISE EXCEPTION 'financial movements can only be added to a draft transaction'; END IF; IF TG_OP='UPDATE' AND (COALESCE((SELECT status FROM financial_transactions WHERE id=OLD.transaction_id),'') <> 'DRAFT' OR COALESCE((SELECT status FROM financial_transactions WHERE id=NEW.transaction_id),'') <> 'DRAFT') THEN RAISE EXCEPTION 'posted financial movements are immutable'; END IF; IF TG_OP='DELETE' AND COALESCE((SELECT status FROM financial_transactions WHERE id=OLD.transaction_id),'') <> 'DRAFT' THEN RAISE EXCEPTION 'posted financial movements are immutable'; END IF; RETURN COALESCE(NEW, OLD); END $$;
CREATE TRIGGER financial_movements_guard BEFORE INSERT OR UPDATE OR DELETE ON financial_movements FOR EACH ROW EXECUTE FUNCTION idm_movement_guard();
CREATE FUNCTION idm_transaction_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE movement_count integer; BEGIN IF idm_migration_mode() THEN RETURN COALESCE(NEW, OLD); END IF; IF TG_OP='INSERT' THEN IF NEW.status <> 'DRAFT' THEN RAISE EXCEPTION 'financial transactions must start as drafts'; END IF; RETURN NEW; END IF; IF TG_OP='DELETE' THEN IF OLD.status <> 'DRAFT' THEN RAISE EXCEPTION 'posted financial transactions cannot be deleted'; END IF; RETURN OLD; END IF; IF OLD.status='DRAFT' AND NEW.status NOT IN ('DRAFT','POSTED') OR OLD.status='POSTED' AND NEW.status NOT IN ('POSTED','VOIDED') OR OLD.status='VOIDED' AND NEW.status <> 'VOIDED' THEN RAISE EXCEPTION 'invalid financial transaction status transition'; END IF; IF OLD.status IN ('POSTED','VOIDED') AND NOT (OLD.status='POSTED' AND NEW.status='VOIDED' AND NEW.id=OLD.id AND NEW.type=OLD.type AND NEW.occurred_at=OLD.occurred_at AND NEW.reference IS NOT DISTINCT FROM OLD.reference AND NEW.description IS NOT DISTINCT FROM OLD.description AND NEW.category IS NOT DISTINCT FROM OLD.category AND NEW.idempotency_key=OLD.idempotency_key AND NEW.created_at=OLD.created_at AND NEW.created_by_user_id IS NOT DISTINCT FROM OLD.created_by_user_id AND NEW.posted_at=OLD.posted_at AND NEW.reversal_of_transaction_id IS NOT DISTINCT FROM OLD.reversal_of_transaction_id) THEN RAISE EXCEPTION 'posted financial transactions are immutable except for a traced void'; END IF; IF OLD.status='DRAFT' AND NEW.status='POSTED' THEN SELECT count(*) INTO movement_count FROM financial_movements WHERE transaction_id=NEW.id; IF movement_count=0 THEN RAISE EXCEPTION 'posted financial transactions require movements'; END IF; IF NEW.type='TRANSFER' AND (movement_count<>2 OR (SELECT coalesce(sum(amount_minor),0) FROM financial_movements WHERE transaction_id=NEW.id)<>0 OR (SELECT count(DISTINCT account_id) FROM financial_movements WHERE transaction_id=NEW.id)<>2 OR (SELECT count(DISTINCT a.currency) FROM financial_movements m JOIN financial_accounts a ON a.id=m.account_id WHERE m.transaction_id=NEW.id)<>1) THEN RAISE EXCEPTION 'transfers require two distinct same-currency compensating movements'; END IF; IF NEW.reversal_of_transaction_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM financial_transactions WHERE id=NEW.reversal_of_transaction_id AND status='POSTED') THEN RAISE EXCEPTION 'a reversal must compensate a posted transaction'; END IF; IF NEW.reversal_of_transaction_id IS NOT NULL AND EXISTS(SELECT 1 FROM (SELECT account_id,sum(amount_minor) n FROM financial_movements WHERE transaction_id IN (NEW.id,NEW.reversal_of_transaction_id) GROUP BY account_id) x WHERE n<>0) THEN RAISE EXCEPTION 'a reversal must exactly compensate every affected account'; END IF; END IF; IF OLD.status='POSTED' AND NEW.status='VOIDED' AND NOT EXISTS(SELECT 1 FROM financial_transactions WHERE reversal_of_transaction_id=OLD.id AND status='POSTED') THEN RAISE EXCEPTION 'voiding requires a posted compensating transaction'; END IF; RETURN NEW; END $$;
CREATE TRIGGER financial_transactions_guard BEFORE INSERT OR UPDATE OR DELETE ON financial_transactions FOR EACH ROW EXECUTE FUNCTION idm_transaction_guard();
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES FROM anon, authenticated;
